 b0=-(p[b]-p[a]);b1=p[c]-p[b];b2=p[d]-p[c];b1/=np.linalg.norm(b1);v=b0-np.dot(b0,b1)*b1;w=b2-np.dot(b2,b1)*b1
 return np.degrees(np.arctan2(np.dot(np.cross(b1,v),w),np.dot(v,w)))
